import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../repositories/providers.dart';
class FarmersScreen extends ConsumerWidget{const FarmersScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Farmer Hub')),floatingActionButton:FloatingActionButton(onPressed:()=>showComingSoon(context,'Image uploads'),child:const Icon(Icons.add_a_photo_outlined)),body:ListView(padding:const EdgeInsets.all(16),children:[for(final r in ref.watch(mockRepositoryProvider).farmerGuides()) ZayloCard(child:ListTile(title:Text(r.title),subtitle:Text('${r.category} • ${r.description}'))),...['Market prices','Weather placeholder','Farming discussions','Land-planning placeholder'].map((x)=>ListTile(title:Text(x),onTap:()=>showComingSoon(context,x)))]));}
